13. Define a 'printArray' function to print the elements of the array.
14. In the 'main' method, print the original array, call the 'mergeSort' function to sort the array, and then print the sorted array.

public class MergeSort {

    public static void main(String[] args) {
        String[] array = {"apple", "banana", "kiwi", "mango", "pear", "peach", "grape"};
        System.out.println("Original Array:");
        printArray(array);

        mergeSort(array);
        System.out.println("\nSorted Array:");
        printArray(array);
    }

    // Merge sort function
    public static void mergeSort(String[] array) {
        if (array.length < 2) {
            return;
        }
        int mid = array.length / 2;
        String[] left = new String[mid];
        String[] right = new String[array.length - mid];

        for (int i = 0; i < mid; i++) {
            left[i] = array[i];
        }
        for (int i = mid; i < array.length; i++) {
            right[i - mid] = array[i];
        }
        mergeSort(left);
        mergeSort(right);
        merge(array, left, right);
    }

    // Merge function to combine two sorted arrays
    public static void merge(String[] array, String[] left, String[] right) {
        int i = 0, j = 0, k = 0;

        while (i < left.length && j < right.length) {
            if (left[i].compareToIgnoreCase(right[j]) <= 0) {
                array[k++] = left[i++];
            } else {
                array[k++] = right[j++];
            }
        }
        while (i < left.length) {
            array[k++] = left[i++];
        }
        while (j < right.length) {
            array[k++] = right[j++];
        }
    }

    // Function to print the array elements
    public static void printArray(String[] array) {
        for (String s : array) {
            System.out.print(s + " ");
        }
    }
}

