def is\_lapindrome(s):
# Step 8:  Check if the length of the string is even.

    if len(s) % 2 == 0:
# Step 9:  If it is, split the string into two halves and create a frequency map for each half.

        half\_length = len(s) // 2
        first\_half = s[:half\_length]
        second\_half = s[half\_length:]

        # Step 10:  Compare the frequency maps of the two halves and return the result.

        return compare\_frequency\_map(first\_half, second\_half)
    else:
# Step 11:  If the length is odd, remove the middle character and repeat the process.

        middle\_index = len(s) // 2
        first\_half = s[:middle\_index]
        second\_half = s[middle\_index+1:]

        return compare\_frequency\_map(first\_half, second\_half)

# Step 12:  Define a function to compare the frequency maps of two strings. This function should take two strings as input and return a boolean value indicating if they have the same frequency of each character.
